using System.Text.Json;
using Strata.Core.Content;
using Strata.Core.Content.Loading;

namespace Strata.Core.Presentation;

/// <summary>
/// The interface's colour-blind palettes (data/config/color_vision.json, generated by tools/content/gen_color_vision.py):
/// per mode, the key UI colours (rarity tiers, chat and caption colours, tooltip bonus and penalty lines) replaced by
/// tuned ones, so the colours of each <see cref="Groups"/> entry stay apart as that viewer sees them. Colours not listed
/// (white text, greys, the animated Expert and Master tiers) are unchanged.
/// </summary>
public sealed class ColorVisionPalette
{
    public const string Path = "data/config/color_vision.json";

    public string? Notes { get; init; }

    /// <summary>The closest pair of a group, as the viewer sees it, must be at least this far apart (CIE76 ΔE).</summary>
    public double MinDistance { get; init; } = 12;

    /// <summary>Colours ("#rrggbb") that must stay distinguishable from each other, by group name.</summary>
    public Dictionary<string, List<string>> Groups { get; init; } = new();

    /// <summary>Per mode name (<see cref="ColorVision.ModeNames"/>): original colour → replacement.</summary>
    public Dictionary<string, Dictionary<string, string>> Modes { get; init; } = new();

    private readonly Dictionary<Rgb, Rgb>?[] _remaps = new Dictionary<Rgb, Rgb>?[ColorVision.ModeNames.Length];

    public static ColorVisionPalette Load(IDataSource data) =>
        JsonSerializer.Deserialize<ColorVisionPalette>(data.ReadText(Path), ContentJson.Options) ?? throw new JsonException($"{Path} is empty");

    /// <summary>The colour shown for <paramref name="c"/> in <paramref name="mode"/> (no allocation after the first call per mode).</summary>
    public Rgb Apply(Rgb c, ColorBlindMode mode)
    {
        if (mode == ColorBlindMode.Off) return c;
        return Remap(mode).TryGetValue(c, out var to) ? to : c;
    }

    /// <summary>The replacements of <paramref name="mode"/> (malformed entries are skipped; <see cref="Validate"/> reports them).</summary>
    public IReadOnlyDictionary<Rgb, Rgb> Remap(ColorBlindMode mode)
    {
        if (_remaps[(int)mode] is { } cached) return cached;
        var map = new Dictionary<Rgb, Rgb>();
        if (Modes.TryGetValue(ColorVision.Name(mode), out var entries))
            foreach (var (from, to) in entries)
                if (ColorVision.TryParseHex(from, out var f) && ColorVision.TryParseHex(to, out var t)) map[f] = t;
        return _remaps[(int)mode] = map;
    }

    /// <summary>The smallest seen distance between two colours of <paramref name="group"/> in <paramref name="mode"/>.</summary>
    public double ClosestPair(string group, ColorBlindMode mode, bool remapped = true)
    {
        var colors = new List<Rgb>();
        foreach (var hex in Groups[group])
            if (ColorVision.TryParseHex(hex, out var c)) colors.Add(remapped ? Apply(c, mode) : c);
        double closest = double.MaxValue;
        for (int i = 0; i < colors.Count; i++)
            for (int j = i + 1; j < colors.Count; j++)
                closest = Math.Min(closest, ColorVision.SeenDistance(colors[i], colors[j], mode));
        return closest;
    }

    public List<string> Validate()
    {
        var problems = new List<string>();
        foreach (var (group, colors) in Groups)
            foreach (var hex in colors)
                if (!ColorVision.TryParseHex(hex, out _)) problems.Add($"group {group}: '{hex}' is not a #rrggbb colour");
        foreach (var (name, entries) in Modes)
        {
            var mode = ColorVision.Parse(name);
            if (mode == ColorBlindMode.Off)
            {
                problems.Add($"unknown mode '{name}' (expected {string.Join(", ", ColorVision.ModeNames.Skip(1))})");
                continue;
            }
            foreach (var (from, to) in entries)
                if (!ColorVision.TryParseHex(from, out _) || !ColorVision.TryParseHex(to, out _))
                    problems.Add($"{name}: '{from}' → '{to}' is not a pair of #rrggbb colours");
        }
        if (problems.Count > 0) return problems;
        for (int m = 1; m < ColorVision.ModeNames.Length; m++)
            foreach (var group in Groups.Keys)
            {
                double closest = ClosestPair(group, (ColorBlindMode)m);
                if (closest < MinDistance)
                    problems.Add($"{ColorVision.ModeNames[m]}: two '{group}' colours are only ΔE {closest:0.0} apart (at least {MinDistance} wanted)");
            }
        return problems;
    }
}
